-- Rev 2.0: documentation is decoupled from check-out. Which services need a note at all (Service.requiresNote), whether a
-- given visit does (Encounter.noteRequired, fixed when the patient is checked in), and whether a signature came after the
-- patient had already been checked out (NoteSignature.afterCheckout). No new table, so no new Row Level Security to enable.
-- Generated by `prisma migrate diff`; the section after the marker is hand-written.

-- AlterTable
ALTER TABLE "Encounter" ADD COLUMN     "noteRequired" BOOLEAN NOT NULL DEFAULT false;

-- AlterTable
ALTER TABLE "NoteSignature" ADD COLUMN     "afterCheckout" BOOLEAN;

-- AlterTable
ALTER TABLE "Service" ADD COLUMN     "requiresNote" BOOLEAN NOT NULL DEFAULT true;


-- =============================================================================
-- HAND-WRITTEN
-- =============================================================================

-- The owner's rule: only what a chiropractor, a nurse practitioner or an IV-lounge nurse delivers needs a note; red light,
-- hyperbaric and similar sessions need none. Every service keeps the column default (true) except these. Mirrored in the seed
-- for a new database; an administrator changes it afterwards on Configuration → Services.
UPDATE "Service" SET "requiresNote" = false WHERE "slug" IN ('red-light-therapy', 'hyperbaric-oxygen-therapy', 'body-composition');

-- Existing visits: one the patient was checked in for takes its service's value as set just above. A visit that never started
-- (scheduled, or a no-show) needs no note. Signed or not is not stored here — the NoteSignature row says that.
UPDATE "Encounter" e SET "noteRequired" = s."requiresNote"
FROM "Booking" b JOIN "Service" s ON s."id" = b."serviceId"
WHERE b."id" = e."bookingId" AND e."status" IN ('CHECKED_IN', 'IN_PROGRESS', 'SEEN', 'CHECKED_OUT');

-- A visit's requirement is fixed when the patient is checked in: the service's requiresNote at that moment, so a later change to
-- the service neither floods anyone's worklist with old visits nor hides notes that were due. A trigger, not application code,
-- because a walk-in's encounter is created inside the scheduling engine (lib/scheduling.ts), which this phase does not touch —
-- and because then nothing that checks a patient in can forget it. It reads; it never changes `status`.
--   entering a checked-in state (from nothing, SCHEDULED or NO_SHOW)  → copy the service's requiresNote
--   back to SCHEDULED, or NO_SHOW                                      → false (there is no visit to document)
--   moving between checked-in states (IN_PROGRESS, SEEN, CHECKED_OUT) → unchanged
CREATE OR REPLACE FUNCTION nw_encounter_note_required() RETURNS trigger AS $$
DECLARE
  here     boolean := NEW."status" IN ('CHECKED_IN', 'IN_PROGRESS', 'SEEN', 'CHECKED_OUT');
  was_here boolean := false;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    was_here := OLD."status" IN ('CHECKED_IN', 'IN_PROGRESS', 'SEEN', 'CHECKED_OUT');
  END IF;
  IF here AND NOT was_here THEN
    NEW."noteRequired" := COALESCE((
      SELECT s."requiresNote" FROM "Booking" b JOIN "Service" s ON s."id" = b."serviceId" WHERE b."id" = NEW."bookingId"
    ), true);
  ELSIF NOT here THEN
    NEW."noteRequired" := false;
  END IF;
  RETURN NEW;
END
$$ LANGUAGE plpgsql;

CREATE TRIGGER "Encounter_note_required" BEFORE INSERT OR UPDATE OF "status" ON "Encounter" FOR EACH ROW EXECUTE FUNCTION nw_encounter_note_required();
